// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        address initialOwner = c.owner();
        bool isCallerOwner = (caller == initialOwner);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        if (isCallerOwner) {
            assertTrue(success && c.owner() == newOwner);
        } else {
            assertTrue(!success || c.owner() == initialOwner);
        }
    }
}
